(function (root) {
    'use strict';

    const synth = root.speechSynthesis;

    function rawVoices() {
        if (!synth) return [];
        try {
            return synth.getVoices() || [];
        } catch (_) {
            return [];
        }
    }

    // Chrome populates the voice list asynchronously the first time it is asked,
    // so an immediate getVoices() on a fresh document often returns []. The
    // 'voiceschanged' event is the documented signal, but it does not fire on
    // every Chrome build once the list is already warm elsewhere in the profile,
    // so poll alongside it and take whichever arrives first.
    function listVoices(timeoutMs = 3000) {
        return new Promise((resolve) => {
            if (!synth) {
                resolve([]);
                return;
            }
            const immediate = rawVoices();
            if (immediate.length > 0) {
                resolve(immediate);
                return;
            }

            let settled = false;
            let pollTimer = null;

            const finish = () => {
                if (settled) return;
                settled = true;
                if (pollTimer !== null) clearInterval(pollTimer);
                synth.removeEventListener('voiceschanged', finish);
                resolve(rawVoices());
            };

            synth.addEventListener('voiceschanged', finish);
            pollTimer = setInterval(() => {
                if (rawVoices().length > 0) finish();
            }, 100);
            setTimeout(finish, timeoutMs);
        });
    }

    function findVoice(id) {
        if (!id) return null;
        const voices = rawVoices();
        return voices.find(v => v.voiceURI === id) ||
               voices.find(v => v.name === id) ||
               null;
    }

    function clamp(value, min, max, fallback) {
        const n = parseFloat(value);
        if (!isFinite(n)) return fallback;
        return Math.min(max, Math.max(min, n));
    }

    // Chrome silently stops any utterance that runs longer than ~15 seconds.
    // Pausing and immediately resuming resets that timer.
    let keepAliveTimer = null;

    function startKeepAlive() {
        stopKeepAlive();
        keepAliveTimer = setInterval(() => {
            if (!synth || !synth.speaking || synth.paused) return;
            synth.pause();
            synth.resume();
        }, 10000);
    }

    function stopKeepAlive() {
        if (keepAliveTimer !== null) {
            clearInterval(keepAliveTimer);
            keepAliveTimer = null;
        }
    }

    let activeToken = 0;

    function cancel() {
        activeToken++;
        stopKeepAlive();
        if (!synth) return;
        try { synth.cancel(); } catch (_) {}
    }

    function pause() {
        if (!synth) return;
        try { synth.pause(); } catch (_) {}
    }

    function resume() {
        if (!synth) return;
        try { synth.resume(); } catch (_) {}
    }

    // opts: { text, voice, rate, pitch, onStart, onBoundary(charIndex), onEnd, onError(message, fatal) }
    function speak(opts) {
        cancel();
        const token = ++activeToken;

        if (!synth) {
            if (opts.onError) opts.onError('Web Speech API unavailable', true);
            return;
        }

        const utterance = new SpeechSynthesisUtterance(opts.text);
        const voice = findVoice(opts.voice);
        if (voice) {
            utterance.voice = voice;
            utterance.lang = voice.lang;
        } else if (opts.voice) {
            // The saved voice is gone (uninstalled, or another profile/machine).
            // Report it so the caller can fall back to another engine.
            if (opts.onError) opts.onError(`Chrome voice "${opts.voice}" is not available`, true);
            return;
        }
        utterance.rate = clamp(opts.rate, 0.1, 10, 1.0);
        utterance.pitch = clamp(opts.pitch, 0, 2, 1.0);

        utterance.onstart = () => {
            if (token !== activeToken) return;
            startKeepAlive();
            if (opts.onStart) opts.onStart();
        };

        utterance.onboundary = (event) => {
            if (token !== activeToken) return;
            if (opts.onBoundary) opts.onBoundary(event.charIndex || 0);
        };

        utterance.onend = () => {
            if (token !== activeToken) return;
            stopKeepAlive();
            if (opts.onEnd) opts.onEnd();
        };

        utterance.onerror = (event) => {
            if (token !== activeToken) return;
            stopKeepAlive();
            const reason = (event && event.error) || 'unknown';
            // Cancelling on purpose surfaces here too — that is not a failure.
            if (reason === 'interrupted' || reason === 'canceled') return;
            if (opts.onError) opts.onError(`Web Speech error: ${reason}`, true);
        };

        // Chrome drops an utterance queued in the same tick as the cancel() above,
        // so let the queue drain first when something was actually speaking.
        if (synth.speaking || synth.pending) {
            setTimeout(() => {
                if (token === activeToken) synth.speak(utterance);
            }, 60);
        } else {
            synth.speak(utterance);
        }
    }

    root.WebSpeech = { listVoices, rawVoices, findVoice, speak, cancel, pause, resume };
})(typeof window !== 'undefined' ? window : globalThis);


// ─── shared/exportPipeline.js ─── 
// Audio Cursor — MP3 export pipeline
//
// The pure part of exporting a long text as one audio file: split it into
// segments the speech services accept, speak them over a small number of
// reused connections, keep the audio in document order, and report progress.
// Nothing in here touches the DOM or extension APIs, so it runs (and is
// tested) under plain node; the offscreen document supplies the connections.
//
// Four rules keep a long export from stalling:
//   * every attempt is bounded by exactly one timeout, owned by the thing that
//     can actually abort the work. Wrapping a timeout around an operation that
//     retries internally only abandons it — it keeps running, unwatched, and
//     holds its connection open;
//   * a failed attempt throws its connection away rather than reusing it, so a
//     retry starts from a clean socket;
//   * one segment gets a fixed budget. When it runs out the segment is skipped
//     and reported, because an export that finishes with a gap is worth more
//     than one that dies at 44% after several silent minutes;
//   * the run says something at least every few seconds. Silence is the one
//     state a caller cannot tell apart from a hang.

// Edge accepts several sentences per request; fewer, larger requests keep a
// long export quick without going near the service's per-message byte cap
// (comfortably under it even at three UTF-8 bytes per character).
const EXPORT_CHUNK_CHARS = 800;
// A segment the service refuses at that size is retried in pieces of the size
// playback uses, which is known to work for every voice.
const RETRY_SPLIT_CHARS = 300;
// Connections open at once, each reused for many parts. Measured end to end on
// a 99-part export: 2 lanes 81s, 4 lanes 18s, 6 lanes 14s. Four takes almost
// all of the win while keeping the number of sockets modest, which matters
// because the browser throttles concurrent handshakes to one address.
const EXPORT_LANES = 4;
// One request. A segment of this size normally answers in about a second, so
// twenty is already deep into "something is wrong" territory.
const SEGMENT_TIMEOUT_MS = 20000;
const CONNECT_TIMEOUT_MS = 12000;
// Tries per segment before it is split, and the waits between them.
const ATTEMPTS_PER_SEGMENT = 3;
const RETRY_BACKOFF_MS = [400, 1200, 3000];
// Parts one connection speaks before it is retired for a fresh one. The
// service slows a connection down the more audio it has produced: measured on
// a 247-part export, holding four connections open throughout took 112s and
// degraded from 5s per 25 parts to 18s once past part 100, while retiring each
// connection every 25 parts held 5s per 25 the whole way and finished in 51s.
// A handshake costs about half a second, so this is nearly free.
const RECYCLE_AFTER_PARTS = 25;
// Total effort for one segment, retries and splits included. Past this it is
// skipped, so a single unspeakable passage cannot hold up the whole export.
const SEGMENT_BUDGET_MS = 75000;
// Say something if nothing has finished for this long.
const WAITING_NOTICE_MS = 8000;
// Nothing finished at all for this long: stop and explain.
const HARD_STALL_MS = 120000;

class CancelledError extends Error {
    constructor() {
        super('Export cancelled');
        this.name = 'CancelledError';
        this.cancelled = true;
    }
}

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Split text into the segments to synthesize for `engine`.
 * @param {string} text
 * @param {'neural'|'cloud'} engine
 * @param {{ neural?: Function, cloud?: Function }} [splitters]
 *   Defaults to the shared chunkers (`ChunkText`, `CloudTTS`) on globalThis.
 * @returns {string[]}
 */
function segmentText(text, engine, splitters = {}) {
    if (!text || typeof text !== 'string' || !text.trim()) return [];
    let pieces;
    if (engine === 'neural') {
        const split = splitters.neural || globalThis.ChunkText.chunkText;
        pieces = split(text, EXPORT_CHUNK_CHARS).map((c) => c.text);
    } else {
        const split = splitters.cloud || globalThis.CloudTTS.chunkSpeechText;
        pieces = split(text);
    }
    return pieces.filter((p) => p && p.trim());
}

/** Join byte arrays into one, ignoring gaps left by skipped segments. */
function concatBytes(arrays) {
    const list = arrays.filter(Boolean);
    const total = list.reduce((n, a) => n + a.byteLength, 0);
    const out = new Uint8Array(total);
    let offset = 0;
    for (const a of list) {
        out.set(a instanceof Uint8Array ? a : new Uint8Array(a), offset);
        offset += a.byteLength;
    }
    return out;
}

/**
 * Speak every segment and return their audio, in order.
 *
 * @param {object} params
 * @param {string[]} params.segments
 * @param {() => Promise<{ speak: (text: string) => Promise<Uint8Array>, close: () => void }>} params.openLane
 *   Opens one connection. Called again whenever a lane's connection is thrown
 *   away, so it must be safe to call many times.
 * @param {number} [params.lanes]
 * @param {number} [params.attempts]
 * @param {number[]} [params.backoff]
 * @param {number} [params.recycleAfter]  Parts before a lane retires its
 *   connection; 0 keeps one connection for the whole run.
 * @param {number} [params.segmentBudgetMs]
 * @param {number} [params.waitingNoticeMs]  0 disables the "still waiting" notices.
 * @param {number} [params.hardStallMs]      0 disables the stall guard.
 * @param {boolean} [params.allowSkips]      Skip a segment that exhausts its budget.
 * @param {(done: number, total: number) => void} [params.onProgress]
 * @param {(note: object) => void} [params.onNotice]
 * @param {() => boolean} [params.isCancelled]
 * @param {() => void} [params.onStall]  Called once when the stall guard trips,
 *   so the caller can abort whatever is in flight (a socket waiting forever
 *   cannot be unwound from here).
 * @param {(index: number) => boolean} [params.hasPart]  True for a part that
 *   was made by an earlier run and does not need speaking again.
 * @param {(index: number, part: any) => any} [params.onPart]  Handed each new
 *   part as it is finished, so a caller can put it somewhere that outlives this
 *   run. When given, finished parts are not also kept in the returned array.
 * @param {Function|null} [params.split]  Re-splitter for a refused segment; null disables.
 * @param {(parts: any[]) => any} [params.combine]  Joins the pieces of a split
 *   segment. Defaults to joining byte arrays; a caller holding its audio as
 *   Blobs passes its own, so nothing has to be a typed array.
 * @returns {Promise<{ parts: Array<Uint8Array|null>, skipped: Array<{segment: number, error: string}> }>}
 */
async function synthesizeSegments({
    segments,
    openLane,
    lanes = EXPORT_LANES,
    attempts = ATTEMPTS_PER_SEGMENT,
    backoff = RETRY_BACKOFF_MS,
    recycleAfter = RECYCLE_AFTER_PARTS,
    segmentBudgetMs = SEGMENT_BUDGET_MS,
    waitingNoticeMs = WAITING_NOTICE_MS,
    hardStallMs = HARD_STALL_MS,
    allowSkips = true,
    onProgress = () => {},
    onNotice = () => {},
    isCancelled = () => false,
    onStall = () => {},
    hasPart = null,
    onPart = null,
    split = (text, max) => globalThis.ChunkText.chunkText(text, max),
    combine = concatBytes
}) {
    const total = segments.length;
    const results = new Array(total).fill(null);
    const skipped = [];
    let next = 0;
    let done = 0;
    let failure = null;
    let stallError = null;
    let lastCompletedAt = Date.now();

    // Something to throw at a lane that is between attempts. A lane already
    // waiting on a request cannot be interrupted from here, which is why the
    // guard also races the whole run below.
    const stopReason = () => {
        if (stallError) return stallError;
        if (failure) return failure;
        if (isCancelled()) return new CancelledError();
        return null;
    };

    async function runLane() {
        let lane = null;
        let spokenOnLane = 0;

        function dropLane() {
            if (!lane) return;
            try { lane.close(); } catch (_) {}
            lane = null;
            spokenOnLane = 0;
        }

        // One attempt: open a connection if this lane has none, speak, and on
        // any failure throw the connection away so the retry starts clean.
        async function attempt(text) {
            // A connection that has already produced a lot of audio is served
            // progressively more slowly, so retire it rather than let the
            // export grind to a halt half way through.
            if (lane && recycleAfter > 0 && spokenOnLane >= recycleAfter) dropLane();
            if (!lane) lane = await openLane();
            try {
                const spoken = await lane.speak(text);
                spokenOnLane++;
                return spoken;
            } catch (err) {
                dropLane();
                throw err;
            }
        }

        async function speakWithRetries(text, segmentNumber, deadline) {
            let lastErr;
            for (let n = 1; n <= attempts; n++) {
                const reason = stopReason();
                if (reason) throw reason;
                if (Date.now() >= deadline) {
                    throw lastErr || new Error('ran out of time for this part');
                }
                try {
                    return await attempt(text);
                } catch (err) {
                    const why = stopReason();
                    if (why) throw why;
                    if (err && err.cancelled) throw new CancelledError();
                    lastErr = err;
                    dropLane();
                    const pause = backoff[Math.min(n - 1, backoff.length - 1)];
                    if (n < attempts && Date.now() + pause < deadline) {
                        onNotice({
                            kind: 'retry',
                            segment: segmentNumber,
                            attempt: n + 1,
                            of: attempts,
                            error: err && err.message
                        });
                        await delay(pause);
                    }
                }
            }
            throw lastErr;
        }

        // A segment the service will not take at full size is retried in
        // smaller pieces before it is given up on.
        async function speakSegment(text, segmentNumber, deadline) {
            try {
                return await speakWithRetries(text, segmentNumber, deadline);
            } catch (err) {
                const why = stopReason();
                if (why) throw why;
                if (err && err.cancelled) throw new CancelledError();
                if (!split || text.length <= RETRY_SPLIT_CHARS || Date.now() >= deadline) throw err;
                onNotice({ kind: 'split', segment: segmentNumber, error: err && err.message });
                const pieces = split(text, RETRY_SPLIT_CHARS)
                    .map((c) => c.text)
                    .filter((p) => p && p.trim());
                const parts = [];
                for (const piece of pieces) {
                    parts.push(await speakWithRetries(piece, segmentNumber, deadline));
                }
                return combine(parts);
            }
        }

        try {
            for (;;) {
                if (stopReason()) return;
                const i = next++;
                if (i >= total) return;
                // Already made by an earlier attempt at this same export.
                if (hasPart && hasPart(i)) {
                    lastCompletedAt = Date.now();
                    onProgress(++done, total);
                    continue;
                }
                const deadline = Date.now() + segmentBudgetMs;
                try {
                    const part = await speakSegment(segments[i], i + 1, deadline);
                    if (onPart) await onPart(i, part);
                    else results[i] = part;
                } catch (err) {
                    if (err && (err.cancelled || err === stallError || err === failure)) return;
                    if (!allowSkips) {
                        if (!failure) failure = err;
                        return;
                    }
                    // Leave a hole rather than throwing the whole export away.
                    skipped.push({ segment: i + 1, error: (err && err.message) || String(err) });
                    onNotice({ kind: 'skip', segment: i + 1, error: err && err.message });
                }
                if (isCancelled()) return;
                lastCompletedAt = Date.now();
                onProgress(++done, total);
            }
        } finally {
            dropLane();
        }
    }

    const width = Math.max(1, Math.min(lanes, total));
    const work = Promise.all(Array.from({ length: width }, () => runLane()));

    // A run that says nothing is indistinguishable from a run that has died,
    // so speak up while waiting, and give up if the wait becomes absurd.
    let ticker = null;
    const watched = (hardStallMs > 0 || waitingNoticeMs > 0)
        ? new Promise((_, rejectStall) => {
            let lastNotice = 0;
            const period = waitingNoticeMs || hardStallMs || 4000;
            const tick = Math.max(100, Math.min(2000, Math.floor(period / 2)));
            const repeatEvery = Math.max(tick, Math.min(4000, period));
            ticker = setInterval(() => {
                const idle = Date.now() - lastCompletedAt;
                if (hardStallMs > 0 && idle > hardStallMs) {
                    clearInterval(ticker);
                    stallError = new Error(
                        `the speech service stopped responding after ${done} of ${total} parts`
                    );
                    try { onStall(); } catch (_) {}
                    rejectStall(stallError);
                    return;
                }
                if (waitingNoticeMs > 0 && idle > waitingNoticeMs && Date.now() - lastNotice > repeatEvery) {
                    lastNotice = Date.now();
                    onNotice({ kind: 'waiting', seconds: Math.round(idle / 1000) });
                }
            }, tick);
        })
        : null;

    try {
        await (watched ? Promise.race([work, watched]) : work);
    } finally {
        clearInterval(ticker);
        // Whatever happens, the lanes must not be left running unwatched.
        work.catch(() => {});
        if (watched) watched.catch(() => {});
    }

    if (stallError) throw stallError;
    if (isCancelled()) throw new CancelledError();
    if (failure) throw failure;
    return { parts: results, skipped };
}

const ExportPipeline = {
    EXPORT_CHUNK_CHARS,
    RETRY_SPLIT_CHARS,
    EXPORT_LANES,
    SEGMENT_TIMEOUT_MS,
    CONNECT_TIMEOUT_MS,
    ATTEMPTS_PER_SEGMENT,
    RETRY_BACKOFF_MS,
    RECYCLE_AFTER_PARTS,
    SEGMENT_BUDGET_MS,
    WAITING_NOTICE_MS,
    HARD_STALL_MS,
    CancelledError,
    segmentText,
    synthesizeSegments,
    concatBytes
};

globalThis.ExportPipeline = ExportPipeline;
if (typeof module !== 'undefined' && module.exports) module.exports = ExportPipeline;


// ─── shared/exportStore.js ─── 
// Audio Cursor — export part store
//
// Finished audio is written to IndexedDB as it is made, one record per part.
// The document that synthesizes an export does not necessarily live as long as
// the export does — Chrome retires an offscreen document it considers idle —
// and everything held only in that document's memory dies with it. Parts kept
// here survive, so an export that is interrupted resumes from where it stopped
// instead of starting again from nothing. That is what lets a selection be
// arbitrarily long: no single run has to finish the whole thing.
//
// Records are keyed `${exportId}:${index padded}`, so one export's parts form a
// contiguous key range and read back in order.

const DB_NAME = 'audio-cursor-export';
const DB_VERSION = 1;
const STORE = 'parts';
// Parts from an export nobody finished are rubbish after this long.
const PART_TTL_MS = 24 * 60 * 60 * 1000;

let dbPromise = null;

function openDb() {
    if (dbPromise) return dbPromise;
    dbPromise = new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onupgradeneeded = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains(STORE)) {
                db.createObjectStore(STORE, { keyPath: 'key' });
            }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error || new Error('Could not open the export store'));
        request.onblocked = () => reject(new Error('The export store is blocked by another window'));
    });
    dbPromise.catch(() => { dbPromise = null; });
    return dbPromise;
}

function partKey(exportId, index) {
    return `${exportId}:${String(index).padStart(6, '0')}`;
}

function rangeFor(exportId) {
    return IDBKeyRange.bound(`${exportId}:`, `${exportId}:￿`);
}

function runTransaction(mode, work) {
    return openDb().then((db) => new Promise((resolve, reject) => {
        const tx = db.transaction(STORE, mode);
        const store = tx.objectStore(STORE);
        let result;
        try {
            result = work(store);
        } catch (err) {
            reject(err);
            return;
        }
        tx.oncomplete = () => resolve(result && result.value !== undefined ? result.value : result);
        tx.onerror = () => reject(tx.error || new Error('Export store transaction failed'));
        tx.onabort = () => reject(tx.error || new Error('Export store transaction aborted'));
    }));
}

/** Store one finished part. */
function putPart(exportId, index, blob) {
    return runTransaction('readwrite', (store) => {
        store.put({ key: partKey(exportId, index), exportId, index, blob, at: Date.now() });
    });
}

/** Which part indices this export has already made. */
function existingIndices(exportId) {
    return runTransaction('readonly', (store) => {
        const out = { value: new Set() };
        const request = store.getAllKeys(rangeFor(exportId));
        request.onsuccess = () => {
            for (const key of request.result) {
                const index = Number(String(key).slice(String(key).lastIndexOf(':') + 1));
                if (Number.isFinite(index)) out.value.add(index);
            }
        };
        return out;
    }).catch(() => new Set());
}

/** Every stored part for this export, in document order. */
function readParts(exportId) {
    return runTransaction('readonly', (store) => {
        const out = { value: [] };
        const request = store.getAll(rangeFor(exportId));
        request.onsuccess = () => {
            out.value = request.result
                .sort((a, b) => a.index - b.index)
                .map((row) => row.blob);
        };
        return out;
    });
}

/** Forget an export, finished or abandoned. */
function deleteExport(exportId) {
    return runTransaction('readwrite', (store) => {
        store.delete(rangeFor(exportId));
    }).catch(() => {});
}

/** Drop parts left behind by exports that were never finished. */
function sweepStale(ttlMs = PART_TTL_MS) {
    return runTransaction('readwrite', (store) => {
        const cutoff = Date.now() - ttlMs;
        const request = store.openCursor();
        request.onsuccess = () => {
            const cursor = request.result;
            if (!cursor) return;
            if (!cursor.value || cursor.value.at < cutoff) cursor.delete();
            cursor.continue();
        };
    }).catch(() => {});
}

/**
 * A stable id for this text and voice, so a second attempt at the same export
 * finds the parts the first one already made.
 */
async function exportIdFor(parts) {
    const source = parts.join('␀');
    try {
        const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(source));
        return Array.from(new Uint8Array(digest).slice(0, 10))
            .map((b) => b.toString(16).padStart(2, '0'))
            .join('');
    } catch (_) {
        // No crypto: a cheap hash still groups one export's parts together.
        let hash = 0;
        for (let i = 0; i < source.length; i++) {
            hash = (hash * 31 + source.charCodeAt(i)) | 0;
        }
        return 'h' + (hash >>> 0).toString(16);
    }
}

globalThis.ExportStore = {
    putPart,
    existingIndices,
    readParts,
    deleteExport,
    sweepStale,
    exportIdFor
};


// ─── offscreen/offscreen.js ─── 
// Audio Cursor — Offscreen Document
// Owns Edge Neural TTS synthesis, MP3 playback, and Chrome's own Web Speech
// voices (window.speechSynthesis), which the background service worker cannot
// reach because speechSynthesis only exists in a document context.
//
// Every chunked-playback message carries an `engine`: 'neural' (synthesize an
// MP3 through Edge TTS, then play it) or 'webspeech' (hand the text to Chrome's
// speechSynthesis). Both report progress and completion the same way, so the
// background worker drives them with one code path.
//
// Synthesis must happen here rather than in the background service worker:
// Chromium does not apply declarativeNetRequest header rules to WebSocket
// upgrade requests initiated from a service worker (crbug.com/1285664), so the
// Origin/User-Agent spoofing in rules.json is silently skipped there and
// speech.platform.bing.com answers the handshake with 403. From a document
// context the rules apply normally.
//
// Protocol (messages from background):
//   { type: 'AC_SYNTH_PLAY',   sessionId, chunkIndex, isLast, engine, text, voice, rate, pitch }
//   { type: 'AC_PREFETCH',     sessionId, chunkIndex, engine, text, voice, rate, pitch }
//   { type: 'AC_PAUSE'  }
//   { type: 'AC_RESUME' }
//   { type: 'AC_STOP'   }
//   { type: 'AC_PREVIEW',      engine, text, voice, rate, pitch }
//   { type: 'AC_PREVIEW_STOP' }
//
// Protocol (messages to background):
//   { type: 'AC_CHUNK_STARTED',  sessionId, chunkIndex }
//   { type: 'AC_CHUNK_PROGRESS', sessionId, chunkIndex, fraction }
//   { type: 'AC_CHUNK_ENDED',    sessionId, chunkIndex, isLast }
//   { type: 'AC_CHUNK_ERROR',    sessionId, chunkIndex, error, fatal }
//   { type: 'AC_PREVIEW_ENDED' }
//   { type: 'AC_PREVIEW_ERROR',  error }

let currentAudio = null;
let currentAudioUrl = null;
let currentSessionId = -1;
let currentEngine = 'neural';
let currentChunkIndex = 0;

// Set by AC_PAUSE, cleared by AC_RESUME or by a new AC_SYNTH_PLAY. A pause that
// lands while a chunk is still being synthesized has no audio element to act on
// yet, so it is remembered here and honoured when the audio finally arrives.
let pausedState = false;

let previewAudio = null;
let previewAudioUrl = null;
let previewToken = 0;

// speechSynthesis is a single global queue shared by page playback and voice
// previews, so remember which of the two is using it. Without this, closing the
// voice picker would silence a page that is mid-read with a Chrome voice.
let webSpeechOwner = null; // 'playback' | 'preview' | null

function cancelWebSpeech(owner) {
    if (typeof WebSpeech === 'undefined') return;
    if (webSpeechOwner !== owner) return;
    webSpeechOwner = null;
    WebSpeech.cancel();
}

// `${sessionId}:${chunkIndex}` -> Promise<base64>
const audioCache = new Map();

function cacheKey(sessionId, chunkIndex) {
    return `${sessionId}:${chunkIndex}`;
}

function post(msg) {
    chrome.runtime.sendMessage(msg, () => void chrome.runtime.lastError);
}

// ── Synthesis ─────────────────────────────────────────────────────────────────

async function synthesizeWithRetry(text, voice, rate, pitch, retries = 2) {
    let lastErr;
    for (let attempt = 0; attempt <= retries; attempt++) {
        try {
            const { base64 } = await EdgeTTS.synthesize(text, voice, rate, pitch);
            if (!base64) throw new Error('Edge TTS returned no audio');
            return base64;
        } catch (err) {
            lastErr = err;
            if (attempt < retries) {
                await new Promise((resolve) => setTimeout(resolve, 250));
            }
        }
    }
    throw lastErr;
}

function getOrSynthesize(sessionId, chunkIndex, text, voice, rate, pitch) {
    const key = cacheKey(sessionId, chunkIndex);
    let pending = audioCache.get(key);
    if (!pending) {
        pending = synthesizeWithRetry(text, voice, rate, pitch);
        audioCache.set(key, pending);
        // Keep a rejected entry from poisoning a later retry of the same chunk.
        pending.catch(() => {
            if (audioCache.get(key) === pending) audioCache.delete(key);
        });
    }
    return pending;
}

// ── Playback ──────────────────────────────────────────────────────────────────

// Detach handlers before tearing an element down. Clearing the source makes the
// element try to load an empty resource, which fires a spurious `error` event —
// if the handlers were still attached that would be reported as a real failure.
function releaseAudio(audio) {
    if (!audio) return;
    audio.onplaying = null;
    audio.ontimeupdate = null;
    audio.onended = null;
    audio.onerror = null;
    try { audio.pause(); } catch (_) {}
    audio.removeAttribute('src');
    try { audio.load(); } catch (_) {}
}

function stopCurrent() {
    releaseAudio(currentAudio);
    currentAudio = null;
    if (currentAudioUrl) {
        try { URL.revokeObjectURL(currentAudioUrl); } catch (_) {}
        currentAudioUrl = null;
    }
    cancelWebSpeech('playback');
}

function base64ToBlobUrl(base64, mimeType = 'audio/mp3') {
    const binary = atob(base64);
    const len = binary.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    const blob = new Blob([bytes], { type: mimeType });
    return URL.createObjectURL(blob);
}

function playMp3(base64, sessionId, chunkIndex, isLast) {
    stopCurrent();

    currentAudioUrl = base64ToBlobUrl(base64);
    const audio = new Audio(currentAudioUrl);
    currentAudio = audio;

    // The only honest "sound is coming out now" signal: everything before it is
    // network and decode time. Reporting playback during that would run the
    // player's progress ahead of the audio.
    audio.onplaying = () => {
        if (sessionId !== currentSessionId) return;
        post({ type: 'AC_CHUNK_STARTED', sessionId, chunkIndex });
    };

    audio.ontimeupdate = () => {
        if (sessionId !== currentSessionId) return;
        const duration = audio.duration;
        if (!duration || !isFinite(duration)) return;
        const fraction = Math.min(1, Math.max(0, audio.currentTime / duration));
        post({ type: 'AC_CHUNK_PROGRESS', sessionId, chunkIndex, fraction });
    };

    audio.onended = () => {
        if (currentAudioUrl) {
            try { URL.revokeObjectURL(currentAudioUrl); } catch (_) {}
            currentAudioUrl = null;
        }
        currentAudio = null;
        if (sessionId === currentSessionId) {
            post({ type: 'AC_CHUNK_ENDED', sessionId, chunkIndex, isLast });
        }
    };

    audio.onerror = () => {
        if (sessionId === currentSessionId) {
            post({
                type: 'AC_CHUNK_ERROR',
                sessionId,
                chunkIndex,
                error: audio.error ? `Audio error code ${audio.error.code}` : 'Audio playback error',
                fatal: false
            });
        }
    };

    if (pausedState) return; // paused while this chunk was still synthesizing

    audio.play().catch((err) => {
        if (sessionId === currentSessionId) {
            post({ type: 'AC_CHUNK_ERROR', sessionId, chunkIndex, error: err.message, fatal: false });
        }
    });
}

// ── Chrome default voices (Web Speech) ────────────────────────────────────────

// Nothing to synthesize here: Chrome speaks the text itself and reports word
// boundaries as it goes, which map straight onto the chunk-progress fractions
// the neural path reports from audio playback position.
function speakWithWebSpeech(msg) {
    const { sessionId, chunkIndex, isLast, text, voice, rate, pitch } = msg;
    stopCurrent();

    const length = text.length || 1;
    webSpeechOwner = 'playback';

    WebSpeech.speak({
        text,
        voice,
        rate,
        pitch,
        onStart: () => {
            if (sessionId !== currentSessionId) return;
            post({ type: 'AC_CHUNK_STARTED', sessionId, chunkIndex });
        },
        onBoundary: (charIndex) => {
            if (sessionId !== currentSessionId) return;
            const fraction = Math.min(1, Math.max(0, charIndex / length));
            post({ type: 'AC_CHUNK_PROGRESS', sessionId, chunkIndex, fraction });
        },
        onEnd: () => {
            if (webSpeechOwner === 'playback') webSpeechOwner = null;
            if (sessionId !== currentSessionId) return;
            post({ type: 'AC_CHUNK_ENDED', sessionId, chunkIndex, isLast });
        },
        onError: (error, fatal) => {
            if (webSpeechOwner === 'playback') webSpeechOwner = null;
            if (sessionId !== currentSessionId) return;
            post({ type: 'AC_CHUNK_ERROR', sessionId, chunkIndex, error, fatal });
        }
    });
}

async function synthAndPlay(msg) {
    const { sessionId, chunkIndex, isLast, text, voice, rate, pitch } = msg;

    if (sessionId !== currentSessionId) {
        // New session: drop anything cached for older ones.
        for (const key of audioCache.keys()) {
            if (!key.startsWith(`${sessionId}:`)) audioCache.delete(key);
        }
        currentSessionId = sessionId;
    }
    currentEngine = msg.engine === 'webspeech' ? 'webspeech' : 'neural';
    currentChunkIndex = chunkIndex;
    pausedState = false;

    if (currentEngine === 'webspeech') {
        speakWithWebSpeech(msg);
        return;
    }

    let base64;
    try {
        base64 = await getOrSynthesize(sessionId, chunkIndex, text, voice, rate, pitch);
    } catch (err) {
        if (sessionId === currentSessionId) {
            post({
                type: 'AC_CHUNK_ERROR',
                sessionId,
                chunkIndex,
                error: (err && err.message) || String(err),
                fatal: true
            });
        }
        return;
    }

    if (sessionId !== currentSessionId) return; // stopped or superseded while synthesizing
    audioCache.delete(cacheKey(sessionId, chunkIndex));
    playMp3(base64, sessionId, chunkIndex, isLast);
}

function prefetch(msg) {
    if (msg.engine === 'webspeech') return;
    const { sessionId, chunkIndex, text, voice, rate, pitch } = msg;
    getOrSynthesize(sessionId, chunkIndex, text, voice, rate, pitch).catch(() => {
        // Errors surface when the chunk is actually played.
    });
}

function doStop() {
    currentSessionId = -1;
    pausedState = false;
    audioCache.clear();
    stopCurrent();
}

// ── Voice preview ─────────────────────────────────────────────────────────────

function stopPreview() {
    // Invalidate any preview still being synthesized so it never starts playing.
    previewToken++;
    cancelWebSpeech('preview');
    releaseAudio(previewAudio);
    previewAudio = null;
    if (previewAudioUrl) {
        try { URL.revokeObjectURL(previewAudioUrl); } catch (_) {}
        previewAudioUrl = null;
    }
}

async function playPreview(msg) {
    stopPreview();
    const token = ++previewToken;

    if (msg.engine === 'webspeech') {
        webSpeechOwner = 'preview';
        WebSpeech.speak({
            text: msg.text,
            voice: msg.voice,
            rate: msg.rate,
            pitch: msg.pitch,
            onEnd: () => {
                if (webSpeechOwner === 'preview') webSpeechOwner = null;
                if (token !== previewToken) return;
                post({ type: 'AC_PREVIEW_ENDED' });
            },
            onError: (error) => {
                if (webSpeechOwner === 'preview') webSpeechOwner = null;
                if (token !== previewToken) return;
                post({ type: 'AC_PREVIEW_ERROR', error });
            }
        });
        return;
    }

    let base64;
    try {
        base64 = await synthesizeWithRetry(msg.text, msg.voice, msg.rate, msg.pitch);
    } catch (err) {
        if (token === previewToken) {
            post({ type: 'AC_PREVIEW_ERROR', error: (err && err.message) || String(err) });
        }
        return;
    }

    if (token !== previewToken) return; // stopped or superseded while synthesizing

    previewAudioUrl = base64ToBlobUrl(base64);
    const audio = new Audio(previewAudioUrl);
    previewAudio = audio;

    audio.onended = () => {
        stopPreview();
        post({ type: 'AC_PREVIEW_ENDED' });
    };
    audio.onerror = () => {
        stopPreview();
        post({ type: 'AC_PREVIEW_ERROR', error: 'Preview playback error' });
    };
    audio.play().catch((err) => {
        stopPreview();
        post({ type: 'AC_PREVIEW_ERROR', error: err.message });
    });
}

// ── Full Audio Export ─────────────────────────────────────────────────────────
//
// The whole job runs here: split, synthesize a few segments at a time, join the
// MP3 frames, and hand the service worker a blob: URL to download. The bytes
// never cross a message as base64 — that is what capped the old export at a
// few minutes of audio — and everything the worker needs to finish the job
// (tab, filename) is echoed back in each message, so it can complete the
// download even if it was restarted while we were busy.

// requestId -> { cancelled, controller }
const activeExports = new Map();

// Export messages travel over a port rather than chrome.runtime.sendMessage.
// A one-shot message to a service worker that is asleep, starting, or shutting
// down can be dropped with nothing but a lastError nobody reads — and a lost
// result message means the audio is made and then thrown away, which looks
// exactly like a hang. A port delivers to a live worker, keeps it awake while
// the export runs, and tells us when it goes away so we can reconnect and say
// it all again.
let exportPort = null;
let exportPortRetry = null;
// The last thing worth repeating to a worker that reconnects.
let exportLastProgress = null;
let exportPendingResult = null;

// The tab whose export is talking, so its log can reach that page's console.
let exportLogTab;

function exportLog(...args) {
    // Mirrored into the page console by the content script, because the
    // offscreen document's own console is buried in chrome://extensions.
    console.log('[Audio Cursor export]', ...args);
    exportSend({ type: 'AC_EXPORT_LOG', tabId: exportLogTab, text: args.map(String).join(' ') }, false);
}

function connectExportPort() {
    if (exportPort) return exportPort;
    try {
        exportPort = chrome.runtime.connect({ name: 'ac-export' });
    } catch (_) {
        exportPort = null;
        return null;
    }
    exportPort.onMessage.addListener((msg) => {
        if (msg && msg.type === 'AC_EXPORT_ACK' && exportPendingResult &&
            msg.requestId === exportPendingResult.requestId) {
            exportPendingResult = null;
        }
    });
    exportPort.onDisconnect.addListener(() => {
        exportPort = null;
        // Keep saying it until someone confirms hearing it: a result that is
        // lost is audio we made and threw away, which looks like a hang.
        if (exportPendingResult) scheduleResultResend();
    });
    return exportPort;
}

function scheduleResultResend(attempt = 0) {
    if (exportPortRetry || !exportPendingResult) return;
    if (attempt > 60) return;
    exportPortRetry = setTimeout(() => {
        exportPortRetry = null;
        if (!exportPendingResult) return;
        exportSend(exportPendingResult, true);
        scheduleResultResend(attempt + 1);
    }, 1000);
}

function exportSend(msg, important = true) {
    const port = connectExportPort();
    if (port) {
        try {
            port.postMessage(msg);
            return;
        } catch (_) {
            exportPort = null;
        }
    }
    // No port available: fall back to a plain message so a worker that is up
    // still hears it, and let the reconnect above try again for a result.
    if (important) post(msg);
}
// requestId -> { url, timer }: blob URLs live until the worker reports the
// download done (AC_EXPORT_RELEASE), or this long, whichever is first.
const exportBlobUrls = new Map();
const EXPORT_URL_TTL_MS = 10 * 60 * 1000;

function rememberExportUrl(requestId, url) {
    const timer = setTimeout(() => releaseExportUrl(requestId), EXPORT_URL_TTL_MS);
    exportBlobUrls.set(requestId, { url, timer });
}

function releaseExportUrl(requestId) {
    const entry = exportBlobUrls.get(requestId);
    if (!entry) return;
    exportBlobUrls.delete(requestId);
    clearTimeout(entry.timer);
    try { URL.revokeObjectURL(entry.url); } catch (_) {}
}

function trackedSend(msg) {
    if (msg.type === 'AC_EXPORT_PROGRESS') exportLastProgress = msg;
    if (msg.type === 'AC_EXPORT_RESULT') {
        exportPendingResult = msg;
        exportSend(msg);
        scheduleResultResend();
        return;
    }
    exportSend(msg);
}

function cancelExport(requestId) {
    const entry = activeExports.get(requestId);
    if (!entry) return;
    entry.cancelled = true;
    // Abort rather than merely stop handing out work: an in-flight request
    // would otherwise hold its connection until it timed out.
    try { entry.controller.abort(); } catch (_) {}
}

const AUDIO_MIME = 'audio/mpeg';

// This document exists under the AUDIO_PLAYBACK reason, and Chrome ties both
// its lifetime and the rate its timers run at to audio actually coming out of
// it. An export plays nothing for minutes on end, so the document was liable
// to be throttled or torn down part way through — which is what an export that
// went silent with no error and no retries actually was. Holding an inaudible
// tone open for the duration keeps the document genuinely active.
let keepAliveCtx = null;
let keepAliveOsc = null;
let keepAliveHolders = 0;

function keepAwake() {
    keepAliveHolders++;
    if (keepAliveCtx) return;
    try {
        const Ctx = self.AudioContext || self.webkitAudioContext;
        keepAliveCtx = new Ctx();
        const gain = keepAliveCtx.createGain();
        // Low enough to be inaudible in practice, loud enough that Chrome
        // counts this document as playing audio rather than idle.
        gain.gain.value = 0.02;
        keepAliveOsc = keepAliveCtx.createOscillator();
        keepAliveOsc.frequency.value = 30;
        keepAliveOsc.connect(gain);
        gain.connect(keepAliveCtx.destination);
        keepAliveOsc.start();
        // It can come up suspended; a suspended context is not audio playing.
        if (keepAliveCtx.state !== 'running') keepAliveCtx.resume().catch(() => {});
        exportLog('keep-awake tone: ' + keepAliveCtx.state);
    } catch (err) {
        exportLog('keep-awake tone failed: ' + ((err && err.message) || err));
        keepAliveCtx = null;
        keepAliveOsc = null;
    }
}

function releaseAwake() {
    keepAliveHolders = Math.max(0, keepAliveHolders - 1);
    if (keepAliveHolders > 0) return;
    try { if (keepAliveOsc) keepAliveOsc.stop(); } catch (_) {}
    try { if (keepAliveCtx) keepAliveCtx.close(); } catch (_) {}
    keepAliveOsc = null;
    keepAliveCtx = null;
}

// Audio is kept as Blobs, never as typed arrays. A long export is tens of
// megabytes, and holding every part in the JavaScript heap — then copying the
// lot again to join them — is what put a ceiling on how much text could be
// exported. Blob data lives in the browser's own store, which spills to disk,
// so joining them at the end costs almost nothing.
function toAudioBlob(bytes) {
    return new Blob([bytes], { type: AUDIO_MIME });
}

function describeNote(note) {
    switch (note.kind) {
        case 'split': return `part ${note.segment} is being split up`;
        case 'skip': return `part ${note.segment} could not be read, skipping it`;
        case 'waiting': return `waiting on the speech service (${note.seconds}s)`;
        default: return `retrying part ${note.segment} (${note.attempt} of ${note.of})`;
    }
}

// Chrome's Web Speech voices cannot be recorded, so exporting one falls back to
// the cloud voice for its language — same as an OS voice does.
async function exportAudio(msg) {
    const { requestId, text, voice, lang, rate, pitch, tabId, filename, voiceName } = msg;
    const echo = { requestId, tabId, filename, voiceName };
    const state = { cancelled: false, controller: new AbortController() };
    activeExports.set(requestId, state);
    const isCancelled = () => state.cancelled;
    const signal = state.controller.signal;
    exportLogTab = tabId;
    keepAwake();

    try {
        const isNeural = msg.engine ? msg.engine === 'neural' : Boolean(voice && voice.includes('Neural'));
        const engine = isNeural ? 'neural' : 'cloud';
        const segments = ExportPipeline.segmentText(text, engine);
        if (!segments.length) throw new Error('Nothing to export');

        // Parts are written to storage as they are made and read back at the
        // end. This document may not outlive the export — Chrome retires an
        // offscreen document it thinks is idle — so anything held only here
        // would be lost. Stored parts mean a second attempt carries on rather
        // than starting again, which is what makes an arbitrarily long
        // selection exportable.
        const exportId = await ExportStore.exportIdFor([voice, String(rate), String(pitch), text]);
        ExportStore.sweepStale();
        const alreadyMade = await ExportStore.existingIndices(exportId);
        if (alreadyMade.size) {
            exportLog(`resuming: ${alreadyMade.size} of ${segments.length} parts already made`);
        }

        // A lane is one connection that speaks many segments in turn. The
        // neural service keeps a socket open for as long as we need it, which
        // is both quicker and gentler than a socket per segment; the cloud
        // endpoint is a plain request, so its lane holds nothing.
        let openLane;
        if (isNeural) {
            openLane = async () => {
                const session = await EdgeTTS.createSession({
                    connectTimeoutMs: ExportPipeline.CONNECT_TIMEOUT_MS
                });
                return {
                    speak: async (segment) => toAudioBlob(await session.speak(segment, voice, rate, pitch, {
                        timeoutMs: ExportPipeline.SEGMENT_TIMEOUT_MS,
                        signal,
                        // A truncated segment would silently drop words from
                        // the file, so a dropped connection is a failure here.
                        resolvePartialOnClose: false
                    })),
                    close: () => session.close()
                };
            };
        } else {
            const langMatch = (lang || voice || '').match(/^[a-z]{2,3}/);
            const langCode = langMatch ? langMatch[0] : 'en';
            openLane = async () => ({
                speak: async (segment) => toAudioBlob(await CloudTTS.fetchCloudAudioBytes(segment, langCode, {
                    signal,
                    timeoutMs: ExportPipeline.SEGMENT_TIMEOUT_MS
                })),
                close: () => {}
            });
        }

        exportLog(`starting: ${segments.length} parts, ${isNeural ? 'neural' : 'cloud'} voice ${voice}`);
        trackedSend({ type: 'AC_EXPORT_PROGRESS', ...echo, done: 0, total: segments.length });

        const { skipped } = await ExportPipeline.synthesizeSegments({
            segments,
            openLane,
            isCancelled,
            // A connection that answers neither audio nor an error cannot be
            // unwound from inside the pipeline; aborting closes its socket.
            onStall: () => { try { state.controller.abort(); } catch (_) {} },
            // Cloud segments are already at the endpoint's limit; only neural
            // ones can be retried in smaller pieces.
            split: isNeural ? undefined : null,
            combine: (pieces) => new Blob(pieces, { type: AUDIO_MIME }),
            hasPart: (index) => alreadyMade.has(index),
            onPart: (index, part) => ExportStore.putPart(exportId, index, part),
            onProgress: (done, total) => trackedSend({ type: 'AC_EXPORT_PROGRESS', ...echo, done, total }),
            onNotice: (note) => {
                if (note.kind !== 'waiting') {
                    exportLog(`${note.kind} part ${note.segment}${note.error ? ': ' + note.error : ''}`);
                }
                trackedSend({
                    type: 'AC_EXPORT_PROGRESS',
                    ...echo,
                    done: null,
                    note: describeNote(note)
                });
            }
        });

        if (isCancelled()) throw new ExportPipeline.CancelledError();

        trackedSend({ type: 'AC_EXPORT_PROGRESS', ...echo, done: null, note: 'assembling the file' });
        const usable = await ExportStore.readParts(exportId);
        if (!usable.length) {
            throw new Error('the speech service returned no audio for any part');
        }

        const blob = new Blob(usable, { type: AUDIO_MIME });
        const blobUrl = URL.createObjectURL(blob);
        rememberExportUrl(requestId, blobUrl);
        // The finished Blob owns its data, so the parts are no longer needed.
        ExportStore.deleteExport(exportId);
        exportLog(`finished: ${usable.length}/${segments.length} parts, ${(blob.size / 1048576).toFixed(1)} MB` +
            (skipped.length ? `, skipped ${skipped.map((s) => s.segment).join(', ')}` : ''));

        trackedSend({
            type: 'AC_EXPORT_RESULT',
            ...echo,
            success: true,
            blobUrl,
            size: blob.size,
            segments: segments.length,
            skipped: skipped.length
        });
    } catch (err) {
        const cancelled = Boolean((err && err.cancelled) || isCancelled());
        if (!cancelled) exportLog('failed: ' + ((err && err.message) || String(err)));
        trackedSend({
            type: 'AC_EXPORT_RESULT',
            ...echo,
            success: false,
            cancelled,
            error: cancelled ? 'Export cancelled' : ((err && err.message) || String(err))
        });
    } finally {
        activeExports.delete(requestId);
        releaseAwake();
    }
}

// ── Message router ────────────────────────────────────────────────────────────

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    switch (message.type) {
        // "Are you still there?" — an export that has gone quiet is either a
        // slow speech service or a document that is no longer running, and
        // those need opposite responses.
        case 'AC_EXPORT_QUERY':
            sendResponse({
                alive: true,
                running: activeExports.has(message.requestId),
                progress: exportLastProgress || null
            });
            return;
        case 'AC_SYNTH_PLAY':
            synthAndPlay(message);
            break;
        case 'AC_PREFETCH':
            prefetch(message);
            break;
        case 'AC_PAUSE':
            pausedState = true;
            if (currentEngine === 'webspeech') WebSpeech.pause();
            else if (currentAudio) currentAudio.pause();
            break;
        case 'AC_RESUME':
            pausedState = false;
            if (currentEngine === 'webspeech') {
                // speechSynthesis has no "resumed" event, and an utterance only
                // fires onstart once — so confirm playback here instead. The
                // neural path gets its confirmation from the audio element.
                WebSpeech.resume();
                if (currentSessionId !== -1) {
                    post({ type: 'AC_CHUNK_STARTED', sessionId: currentSessionId, chunkIndex: currentChunkIndex });
                }
            } else if (currentAudio) {
                currentAudio.play().catch(() => {});
            }
            break;
        case 'AC_STOP':
            doStop();
            break;
        case 'AC_PREVIEW':
            playPreview(message);
            break;
        case 'AC_PREVIEW_STOP':
            stopPreview();
            break;
        case 'AC_EXPORT_AUDIO':
            exportAudio(message);
            break;
        case 'AC_EXPORT_CANCEL':
            cancelExport(message.requestId);
            break;
        case 'AC_EXPORT_RELEASE':
            releaseExportUrl(message.requestId);
            break;
    }
});


